function makeG3Question(id,stageOverride=null){
 const raw=rawCourseId(id),d=stageOverride===null?activeDifficulty():Math.max(0,Math.min(2,Number(stageOverride)||0));
 if(raw==="classification_patterns")return g3ClassificationPatternsQuestion(d);
 if(raw==="true_false_logic")return g3TrueFalseLogicQuestion(d);
 if(raw==="tables")return g3TableQuestion(d);
 if(raw==="bar_charts")return g3BarChartsQuestion(d);
 if(raw==="algorithms_logic")return g3AlgorithmsLogicQuestion(d);
 if(g3WrittenMode(raw))return null;
 if(raw==="geometry_figures")return g3GeometryFiguresQuestion(d);
 if(raw==="geometry_construction")return g3GeometryConstructionQuestion(d);
 if(raw==="broken_line_length")return g3BrokenLineQuestion(d);
 if(raw==="perimeter")return g3PerimeterQuestion(d);
 if(raw==="area_measure")return g3AreaMeasureQuestion(d);
 if(raw==="rectangle_square_area")return g3RectangleSquareAreaQuestion(d);
 if(raw==="task_model")return g3TaskModelQuestion(d);
 if(raw==="operation_word_problems")return g3OperationWordQuestion(d);
 if(raw==="difference_compare_tasks")return g3DifferenceStoryQuestion(d);
 if(raw==="multiplicative_compare_tasks")return g3MultiplicativeStoryQuestion(d);
 if(raw==="increase_decrease_tasks")return g3IncreaseDecreaseStoryQuestion(d);
 if(raw==="price_quantity_cost")return g3PriceQuestion(d);
 if(raw==="time_tasks")return g3TimeStoryQuestion(d);
 if(raw==="remainder_tasks")return g3RemainderTaskQuestion(d);
 if(raw==="two_step_tasks")return g3TwoStepQuestion(d);
 if(raw==="parts_intro")return g3PartsIntroQuestion(d);
 if(raw==="parts_compare")return g3PartsCompareQuestion(d);
 if(raw==="part_of_quantity")return g3PartOfQuantityQuestion(d);

 if(raw==="division_remainder"){
  const divisor=ri(2,9),qv=ri(d===0?2:3,d===0?9:d===1?15:25),rem=ri(1,divisor-1),dividend=divisor*qv+rem;
  const base=`${divisor} · ${qv} = ${divisor*qv}.<br>${dividend} − ${divisor*qv} = ${rem}.<br>Проверка: ${dividend} = ${divisor} · ${qv} + ${rem}, причём ${rem} меньше ${divisor}.`;
  if(d===0)return g3RemainderInputQuestion(dividend,divisor,qv,rem,`${base}<br>Ответ: <b>${qv} (ост. ${rem})</b>.`,`g3:${raw}:${d}:numeric:${dividend}:${divisor}`,{stage:d,variant:"numeric"});
  if(d===1){
   const apples=Math.random()<.5,variant=apples?"packApples":"packPencils";
   const question=g3RemainderInputQuestion(dividend,divisor,qv,rem,`${base}<br>Получилось <b>${qv} полных упаковок</b>, осталось <b>${rem}</b>.`,`g3:${raw}:${d}:${variant}:${dividend}:${divisor}`,{stage:d,variant});
   question.text=apples?`${g3Qty(dividend,"apple")} раскладывают по ${g3Qty(divisor,"apple")} в пакет. Сколько полных пакетов получится и сколько яблок останется?`:`${g3Qty(dividend,"pencil")} раскладывают по ${g3Qty(divisor,"pencil")} в коробку. Сколько полных коробок получится и сколько карандашей останется?`;
   return question;
  }
  const taken=ri(3,12),total=dividend+taken,variant="subtractThenDivide";
  const question=g3RemainderInputQuestion(dividend,divisor,qv,rem,`Сначала найдём, сколько осталось после выдачи: ${total} − ${taken} = ${dividend}.<br>Делим оставшиеся по ${divisor}.<br>${base}<br>Ответ: <b>${qv} полных коробок, ${rem} карандашей осталось</b>.`,`g3:${raw}:${d}:${variant}:${total}:${taken}:${divisor}`,{stage:d,variant,total,taken});
  question.text=`Было ${g3Qty(total,"pencil")}. ${g3Qty(taken,"pencil")} отдали. Остальные раскладывают по ${g3Qty(divisor,"pencil")} в коробку. Сколько полных коробок получится и сколько карандашей останется?`;
  return question;
 }
 if(raw==="properties"){const variants=d===0?["commAdd","commMul"]:d===1?["commAdd","commMul","assocAdd","assocMul"]:["assocAdd","assocMul","convenientAdd","convenientMul"],v=g6RandomFrom(variants);let text,answer,ex,audit={type:"g3Properties",variant:v};if(v==="commAdd"){const a=ri(10,80),b=ri(2,40);answer=a;text=`${a} + ${b} = ${b} + □`;ex=`При перестановке слагаемых сумма не меняется. Значит □ = <b>${a}</b>.`;audit={...audit,a,b,answer}}else if(v==="commMul"){const a=ri(2,9),b=ri(2,9);answer=a;text=`${a} · ${b} = ${b} · □`;ex=`При перестановке множителей произведение не меняется. Значит □ = <b>${a}</b>.`;audit={...audit,a,b,answer}}else if(v==="assocAdd"){const a=ri(10,40),b=ri(10,40),c=100-b;answer=a+b+c;text=`(${a} + ${b}) + ${c}`;ex=`Можно перегруппировать: ${a} + (${b} + ${c}) = ${a} + 100 = <b>${answer}</b>.`;audit={...audit,a,b,c,answer}}else if(v==="assocMul"){const a=g6RandomFrom([2,5]),b=ri(2,9),c=a===2?5:2;answer=a*b*c;text=`${a} · ${b} · ${c}`;ex=`Удобно сначала ${a} · ${c} = 10, затем 10 · ${b} = <b>${answer}</b>.`;audit={...audit,a,b,c,answer}}else if(v==="convenientAdd"){const a=g6RandomFrom([25,35,45,55,65,75]),c=100-a,b=ri(10,89);answer=a+b+c;text=`${a} + ${b} + ${c}`;ex=`Удобно сложить ${a} + ${c} = 100, затем 100 + ${b} = <b>${answer}</b>.`;audit={...audit,a,b,c,answer}}else{const a=g6RandomFrom([2,5]),c=a===2?5:2,b=ri(2,9);answer=a*b*c;text=`${a} · ${b} · ${c}`;ex=`Удобно сгруппировать ${a} · ${c} = 10, затем 10 · ${b} = <b>${answer}</b>.`;audit={...audit,a,b,c,answer}}return g6NumberInputQuestion(`Вычислите удобным способом: <b>${text}</b>.`,answer,ex,`g3:${raw}:${d}:${v}:${Object.values(audit).slice(2).join(":")}`,{audit})}
 if(raw==="unknown_component")return g3UnknownQuestion(d);
 if(raw==="order_operations")return g3OrderQuestion(d);
 if(raw==="quantity_operations")return g3QuantityQuestion(d);
 if(raw==="multiplication_table"){
  const max=d===0?5:9,fact=multiplicationFactCandidate(2,max),a=fact.a,b=fact.b,product=a*b,variant=d===2&&Math.random()<.38?g6RandomFrom(["unknownA","unknownB"]):"product";
  if(variant==="unknownA")return g6NumberInputQuestion(`<b>? · ${b} = ${product}</b>`,a,`${a} · ${b} = ${product}. Значит, неизвестный множитель — <b>${a}</b>.`,`g3:${raw}:${d}:unknownA:${a}:${b}`,{audit:{type:"g3MulTable",variant,a,b,product,answer:rational(a,1)}});
  if(variant==="unknownB")return g6NumberInputQuestion(`<b>${a} · ? = ${product}</b>`,b,`${a} · ${b} = ${product}. Значит, неизвестный множитель — <b>${b}</b>.`,`g3:${raw}:${d}:unknownB:${a}:${b}`,{audit:{type:"g3MulTable",variant,a,b,product,answer:rational(b,1)}});
  const pair=[Math.min(a,b),Math.max(a,b)];return g6NumberInputQuestion(`<b>${a} · ${b}</b> = ?`,product,`${a} · ${b} = <b>${product}</b>.`,`g3:${raw}:${d}:product:${pair[0]}:${pair[1]}`,{audit:{type:"g3MulTable",variant,a,b,product,answer:rational(product,1)}});
 }
 if(raw==="division_table"){
  const max=d===0?6:9,fact=multiplicationFactCandidate(2,max),a=fact.a,b=fact.b,product=a*b,byA=Math.random()<.5,divisor=byA?a:b,quotient=byA?b:a,variant=d===2&&Math.random()<.38?g6RandomFrom(["unknownDividend","unknownDivisor"]):"quotient";
  if(variant==="unknownDividend")return g6NumberInputQuestion(`<b>? : ${divisor} = ${quotient}</b>`,product,`${quotient} · ${divisor} = ${product}, поэтому <b>${product} : ${divisor} = ${quotient}</b>.`,`g3:${raw}:${d}:unknownDividend:${product}:${divisor}:${quotient}`,{audit:{type:"g3DivTable",variant,product,divisor,quotient,answer:rational(product,1)}});
  if(variant==="unknownDivisor")return g6NumberInputQuestion(`<b>${product} : ? = ${quotient}</b>`,divisor,`${quotient} · ${divisor} = ${product}, поэтому неизвестный делитель — <b>${divisor}</b>.`,`g3:${raw}:${d}:unknownDivisor:${product}:${divisor}:${quotient}`,{audit:{type:"g3DivTable",variant,product,divisor,quotient,answer:rational(divisor,1)}});
  return g6NumberInputQuestion(`<b>${product} : ${divisor}</b> = ?`,quotient,`${product} : ${divisor} = <b>${quotient}</b>, потому что ${divisor} · ${quotient} = ${product}.`,`g3:${raw}:${d}:quotient:${product}:${divisor}`,{audit:{type:"g3DivTable",variant,product,divisor,quotient,answer:rational(quotient,1)}});
 }

 if(raw==="offtable_multiply"){
  if(d===0){
   const tens=ri(1,4)*10,k=ri(2,Math.min(7,Math.floor(100/tens))),answer=tens*k;
   return g6NumberInputQuestion(`<b>${tens} · ${k}</b> = ?`,answer,`${tens/10} дес. · ${k} = ${(tens/10)*k} дес. = <b>${answer}</b>.`,`g3:${raw}:${d}:tens:${tens}:${k}`,{audit:{type:"g3OffMul",variant:"tens",n:tens,k,tens,ones:0,answer:rational(answer,1)}});
  }
  if(d===1){
   let n=0,k=0,answer=0,guard=0;
   do{guard++;n=ri(11,32);k=ri(2,4);answer=n*k}while(answer>100&&guard<300);
   if(answer>100){n=23;k=3;answer=69}
   const tens=Math.floor(n/10)*10,ones=n%10,story=Math.random()<.45,variant=story?"equalGroups":"decomp";
   const text=story?`В ${k} коробках по ${g3Qty(n,"pencil")}. Сколько карандашей во всех коробках?`:`<b>${n} · ${k}</b> = ?`;
   const ex=`В каждой группе ${n}, групп ${k}. Раскладываем ${n} = ${tens} + ${ones}.<br>${tens} · ${k} = ${tens*k}; ${ones} · ${k} = ${ones*k}.<br>${tens*k} + ${ones*k} = <b>${answer}</b>.`;
   return g6NumberInputQuestion(text,answer,ex,`g3:${raw}:${d}:${variant}:${n}:${k}`,{audit:{type:"g3OffMul",variant,n,k,tens,ones,answer:rational(answer,1)}});
  }
  const n=ri(21,45),k=ri(2,4),product=n*k,delta=ri(3,Math.min(18,product-1)),plus=Math.random()<.5,variant=plus?"multiplyThenAdd":"multiplyThenSubtract",answer=product+(plus?delta:-delta);
  const text=plus?`На ${k} полках по ${g3Qty(n,"book")}. Принесли ещё ${g3Qty(delta,"book")}. Сколько книг стало всего?`:`На ${k} полках по ${g3Qty(n,"book")}. С полок забрали ${g3Qty(delta,"book")}. Сколько книг осталось?`;
  const tens=Math.floor(n/10)*10,ones=n%10;
  const ex=`Сначала находим количество на полках: ${n} = ${tens} + ${ones}; ${tens} · ${k} = ${tens*k}; ${ones} · ${k} = ${ones*k}.<br>${tens*k} + ${ones*k} = ${product}.<br>Затем ${plus?"прибавляем":"вычитаем"}: ${product} ${plus?"+":"−"} ${delta} = <b>${answer}</b>.`;
  return g6NumberInputQuestion(text,answer,ex,`g3:${raw}:${d}:${variant}:${n}:${k}:${delta}`,{audit:{type:"g3OffMul",variant,n,k,tens,ones,product,delta,answer:rational(answer,1)}});
 }
 if(raw==="offtable_divide"){
  if(d===0){
   const divisor=g6RandomFrom([2,3,4,5]),unit=ri(1,Math.max(1,Math.floor(9/divisor))),quotient=unit*10,dividend=quotient*divisor;
   return g6NumberInputQuestion(`<b>${dividend} : ${divisor}</b> = ?`,quotient,`${dividend/10} дес. : ${divisor} = ${quotient/10} дес. = <b>${quotient}</b>.`,`g3:${raw}:${d}:tens:${dividend}:${divisor}`,{audit:{type:"g3OffDiv",variant:"tens",dividend,divisor,quotient,tens:dividend,ones:0,answer:rational(quotient,1)}});
  }
  const divisor=g6RandomFrom(d===1?[2,3,4]:[2,3,4,5,6]),parts=g3OfftableDivisionParts(divisor,d)||g3OfftableDivisionParts(2,d),{tens,ones,dividend,quotient}=parts;
  const baseEx=`Разложим ${dividend} = ${tens} + ${ones}.<br>${tens} : ${divisor} = ${tens/divisor}; ${ones} : ${divisor} = ${ones/divisor}.<br>${tens/divisor} + ${ones/divisor} = ${quotient}.`;
  if(d===1){
   const story=Math.random()<.45,variant=story?"equalSharing":"decomp";
   const text=story?`${g3Qty(dividend,"pencil")} разложили поровну в ${g3Qty(divisor,"box")}. Сколько карандашей в каждой коробке?`:`<b>${dividend} : ${divisor}</b> = ?`;
   return g6NumberInputQuestion(text,quotient,`${baseEx}<br>Ответ: <b>${quotient}</b>.`,`g3:${raw}:${d}:${variant}:${dividend}:${divisor}`,{audit:{type:"g3OffDiv",variant,dividend,divisor,quotient,tens,ones,answer:rational(quotient,1)}});
  }
  const delta=ri(2,Math.min(8,quotient-1)),plus=Math.random()<.5,variant=plus?"divideThenAdd":"divideThenSubtract",answer=quotient+(plus?delta:-delta);
  const text=plus?`${g3Qty(dividend,"pencil")} разложили поровну в ${g3Qty(divisor,"box")}. В каждую коробку добавили ещё ${g3Qty(delta,"pencil")}. Сколько карандашей теперь в одной коробке?`:`${g3Qty(dividend,"pencil")} разложили поровну в ${g3Qty(divisor,"box")}. Из каждой коробки взяли ${g3Qty(delta,"pencil")}. Сколько карандашей осталось в одной коробке?`;
  const ex=`${baseEx}<br>Затем ${plus?"прибавляем":"вычитаем"} ${delta}: ${quotient} ${plus?"+":"−"} ${delta} = <b>${answer}</b>.`;
  return g6NumberInputQuestion(text,answer,ex,`g3:${raw}:${d}:${variant}:${dividend}:${divisor}:${delta}`,{audit:{type:"g3OffDiv",variant,dividend,divisor,quotient,tens,ones,delta,answer:rational(answer,1)}});
 }
 if(raw==="round_numbers"){
  const data=g3RoundNumberQuestionData(d);return g6NumberInputQuestion(data.text,data.answer,data.ex,`g3:${raw}:${d}:${data.audit.variant}:${Object.values(data.audit).slice(1,-1).join(":")}`,{audit:{...data.audit,answer:rational(data.answer,1)}});
 }
 if(raw==="zero_one"){
  const simple=d<2||Math.random()<.68,types=["mulOneR","mulOneL","mulZeroR","mulZeroL","divOne","selfDiv","zeroDiv"],variant=simple?g6RandomFrom(d===0?["mulOneR","mulZeroR","divOne","zeroDiv"]:types):g6RandomFrom(["exprMulOne","exprMulZero","exprSelfDiv"]),a=ri(1,d===0?20:d===1?150:500),b=ri(1,9);let text,answer,ex,audit={type:"g3ZeroOne",variant,a,b};
  if(variant==="mulOneR"){text=`<b>${a} · 1</b> = ?`;answer=a;ex=`При умножении на 1 число не меняется: ${a} · 1 = <b>${a}</b>.`}
  else if(variant==="mulOneL"){text=`<b>1 · ${a}</b> = ?`;answer=a;ex=`1 · ${a} = <b>${a}</b>.`}
  else if(variant==="mulZeroR"){text=`<b>${a} · 0</b> = ?`;answer=0;ex=`При умножении любого числа на 0 получается <b>0</b>.`}
  else if(variant==="mulZeroL"){text=`<b>0 · ${a}</b> = ?`;answer=0;ex=`0 · ${a} = <b>0</b>.`}
  else if(variant==="divOne"){text=`<b>${a} : 1</b> = ?`;answer=a;ex=`При делении на 1 число не меняется: ${a} : 1 = <b>${a}</b>.`}
  else if(variant==="selfDiv"){text=`<b>${a} : ${a}</b> = ?`;answer=1;ex=`Ненулевое число, делённое само на себя, равно <b>1</b>.`}
  else if(variant==="zeroDiv"){text=`<b>0 : ${a}</b> = ?`;answer=0;ex=`0 : ${a} = <b>0</b>, потому что ${a} · 0 = 0.`}
  else if(variant==="exprMulOne"){text=`<b>${a} · 1 + ${b}</b> = ?`;answer=a+b;ex=`${a} · 1 = ${a}.<br>${a} + ${b} = <b>${answer}</b>.`}
  else if(variant==="exprMulZero"){text=`<b>${a} · 0 + ${b}</b> = ?`;answer=b;ex=`${a} · 0 = 0.<br>0 + ${b} = <b>${answer}</b>.`}
  else {text=`<b>${a} : ${a} + ${b}</b> = ?`;answer=1+b;ex=`${a} : ${a} = 1.<br>1 + ${b} = <b>${answer}</b>.`}
  return g6NumberInputQuestion(text,answer,ex,`g3:${raw}:${d}:${variant}:${a}:${b}`,{audit:{...audit,answer:rational(answer,1)}});
 }
 if(raw==="numbers_1000"){
  const variants=d===0?["after","before","missing"]:d===1?["after","before","missing","boundary"]:["between","after","before","missing","spoken"],variant=variants[ri(0,variants.length-1)];let text,answer,ex,data={type:"numbers1000",variant};
  if(variant==="after"){const n=d===0?ri(1,99):ri(1,999);answer=n+1;text=`Какое число идёт после <b>${n}</b>?`;ex=`После ${n} идёт число <b>${answer}</b>.`;data.n=n}
  else if(variant==="before"){const n=d===0?ri(2,100):ri(2,1000);answer=n-1;text=`Какое число стоит перед <b>${n}</b>?`;ex=`Перед ${n} стоит число <b>${answer}</b>.`;data.n=n}
  else if(variant==="between"){const n=ri(2,999);answer=n;text=`Какое число находится между <b>${n-1}</b> и <b>${n+1}</b>?`;ex=`Между ${n-1} и ${n+1} находится <b>${n}</b>.`;data.n=n}
  else if(variant==="boundary"){const bases=[9,19,29,39,49,59,69,79,89,99,199,299,399,499,599,699,799,899],n=bases[ri(0,bases.length-1)];answer=n+1;text=`Продолжите ряд: <b>${Math.max(1,n-1)}, ${n}, __, ${n+2}</b>.`;ex=`Числа увеличиваются на 1. После ${n} идёт <b>${answer}</b>.`;data.n=n}
  else if(variant==="spoken"){const special=[105,204,307,400,506,700,901],n=Math.random()<.35?special[ri(0,special.length-1)]:ri(100,999);answer=n;text=`Запишите цифрами: <b>${g3NumberWords(n)}</b>.`;ex=`${g3NumberWords(n)} — это число <b>${n}</b>.`;data.n=n}
  else{const start=d===0?ri(1,96):ri(1,997);answer=start+2;text=`Какое число пропущено: <b>${start}, ${start+1}, __, ${start+3}</b>?`;ex=`Числа идут по порядку. Пропущено <b>${answer}</b>.`;data.start=start}
  return g6NumberInputQuestion(text,answer,ex,`g3:${raw}:${d}:${variant}:${JSON.stringify(data)}`,{audit:{...data,answer:rational(answer,1)}});
 }
 if(raw==="place_value"){
  const variant=d===0?["digitH","digitT","digitO"][ri(0,2)]:d===1?g6RandomFrom(["build","digitH","digitT","digitO"]):g6RandomFrom(["buildZero","decompose","digitH","digitT","digitO"]),special=[105,204,307,400,506,604,700,805,901],n=(d===2&&Math.random()<.45)?special[ri(0,special.length-1)]:ri(100,999),pv=g3PlaceValueParts(n),h=pv.h,t=pv

