function g3CompareQuestion(text,leftBase,rightBase,ex,sig,audit={}){const correct=leftBase<rightBase?"<":leftBase>rightBase?">":"=";return g6ChoiceQuestion(text,correct,["<","=",">"],ex,sig,{type:"g3Compare",leftBase,rightBase,correct,...audit})}
function g3OrderChoiceQuestion(values,ascending,sig){
 const correct=values.slice().sort((a,b)=>ascending?a-b:b-a),rev=correct.slice().reverse(),swap=correct.slice(),rotate=correct.slice();
 if(swap.length>2){const i=ri(0,swap.length-2),t=swap[i];swap[i]=swap[i+1];swap[i+1]=t}rotate.push(rotate.shift());
 const label=a=>a.join(", "),text=`Расположите числа <b>${values.join(", ")}</b> ${ascending?"по возрастанию":"по убыванию"}.`;
 return g6ChoiceQuestion(text,label(correct),[label(rev),label(swap),label(rotate)],`${ascending?"По возрастанию":"По убыванию"}: <b>${label(correct)}</b>.`,sig,{type:"g3Order",values:values.slice(),ascending,answer:correct.slice()});
}
function g3MixedBaseText(parts){return parts.filter(x=>x[0]).map(x=>`${x[0]} ${x[1]}`).join(" ")}

function g3HasCarry(a,b){const cols=Math.max(String(a).length,String(b).length,String(a+b).length);return countMarks(calcCarries(a,b,cols))}
function g3BorrowCount(a,b){const cols=Math.max(String(a).length,String(b).length);return countMarks(calcBorrows(a,b,cols).receive)}
function g3BorrowThroughZero(a,b){const sa=String(a),cols=Math.max(sa.length,String(b).length),br=calcBorrows(a,b,cols);return br.receive.some((x,i)=>x&&i>0&&sa.padStart(cols,"0")[i-1]==="0")||/0/.test(sa)&&g3BorrowCount(a,b)>=2}
function generateG3ColumnTask(topicId,stageIndex){
 const raw=rawCourseId(topicId),d=Math.max(0,Math.min(2,Number(stageIndex)||0));
 if(raw==="written_add"){
  let a=0,b=0,ans=0,carries=0,guard=0;do{guard++;a=ri(d===0?20:100,d===0?599:899);b=ri(d===0?10:40,d===0?399:899);ans=a+b;if(ans>1000)continue;carries=g3HasCarry(a,b)}while(((d===0&&carries!==0)||(d===1&&(carries<1||carries>1))||(d===2&&carries<2)||ans>1000)&&guard<800);
  if(ans>1000||(d===0&&carries)||(d===1&&carries!==1)||(d===2&&carries<2)){[a,b]=d===0?[243,315]:d===1?[268,125]:[487,356];ans=a+b}
  const cols=Math.max(String(a).length,String(b).length,String(ans).length);return {a,b,ans,op:"+",marks:calcCarries(a,b,cols),g3Topic:raw,audit:{type:"g3WrittenAdd",a,b,answer:ans,carries:g3HasCarry(a,b)}};
